use vstd::prelude::*;

verus! {
    fn reverse(a: &[i32]) -> (result: Vec<i32>)
        ensures
            result.len() == a.len() && 
            forall|i: nat| (i < a.len() as nat) ==> (result[i as usize] == a[(a.len() as nat - 1 - i) as usize])
    {
        let mut result: Vec<i32> = Vec::with_capacity(a.len());
        let len = a.len() as nat;

        // Fill the result vector in reverse order
        let mut idx: nat = 0;
        while idx < len
            invariant
                idx <= len,
                result.len() == idx as usize,
                forall|i: nat| (i < idx) ==> (result[i as usize] == a[(len - 1 - i) as usize]),
            decreases len - idx,
        {
            result.push(a[(len - 1 - idx) as usize]);
            idx = idx + 1;
        }

        result
    }
}

